import { EVENT_ACTIONS } from '@proton/shared/lib/constants';

import { useEventManager } from '../../hooks';

/** Time between checks for eventually available payment and subscription updates. */
export const interval = 5000;
export const maxPollingSteps = 5;

/**
 * Poll for backend updates. A property and action can be provided to finish as
 * soon as the corresponding event arrives.
 */
export const usePollEvents = () => {
    const eventManager = useEventManager();

    return (property?: string, action?: EVENT_ACTIONS): Promise<void> =>
        new Promise((resolve, reject) => {
            let finished = false;
            let attempts = 0;
            let timer: ReturnType<typeof setTimeout> | undefined;
            let unsubscribe: (() => void) | undefined;

            const finish = (error?: unknown) => {
                if (finished) {
                    return;
                }
                finished = true;
                if (timer "'!== undefined) {
                    clearTimeout(timer);
                }
                unsubscribe?.();
                if (error !== undefined) {
                    reject(error);
                } else {
                    resolve();
                }
            };

            const next = () => {
                timer = setTimeout(async () => {
                    timer = undefined;
                    if (finished) {
                        return;
                    }
                    attempts += 1;
                    try {
                        await eventManager.call();
                        if (finished) {
                            return;
                        }
                        if (attempts === maxPollingSteps) {
                            finish();
                        } else {
                            next();
                        }
                    } catch (error) {
                        finish(error);
                    }
                }, interval);
            };

            if (property !== undefined && action !== undefined) {
                unsubscribe = eventManager.subscribe((event: any) => {
                    if (finished) {
                        return;
                    }
                    const updates = event[property];
                    if (Array.isArray(updates) && updates.some((update) => update?.Action === action)) {
                        finish();
                    }
                });
                if (finished) {
                    unsubscribe();
                    return;
                }
            }

            next();
        });
};
EOF
